string requestLine = "GET /docs HTTP/1.1";
string[] parts = requestLine.Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (parts.Length != 3 || parts[2] != "HTTP/1.1")
    Console.WriteLine("400");
else if (parts[0] != "GET")
    Console.WriteLine("405");
